 v('season',x.season);v('episode_count',x.episodes);v('duration_minutes',x.duration);v('studio',x.studios?.nodes?.map(s=>s.name).join(', '));v('score',x.averageScore);v('cover_url',x.coverImage?.extraLarge||x.coverImage?.large);v('banner_url',x.bannerImage);v('trailer_url',x.trailer?.site==='youtube'?'https://www.youtube.com/watch?v='+x.trailer.id:'');
 v('characters',JSON.stringify((x.characters?.edges||[]).map(e=>({name:e.node?.name?.full,image:e.node?.image?.large,voice_actor:e.voiceActors?.[0]?.name?.full||'',voice_actor_image:e.voiceActors?.[0]?.image?.large||''})),null,2));
