function slug(s){return String(s||'anime').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,130)||'anime'}
function parsedMeta(f){
 const fd=new FormData(f),g=n=>String(fd.get(n)||'').trim(),json=n=>{try{return JSON.parse(g(n)||'[]')}catch{throw Error('Le JSON des personnages ou des liens est invalide.')}};
 const chars=json('characters'),links=json('external_links');if(!Array.isArray(chars)||!Array.isArray(links))throw Error('Personnages et liens doivent être des listes JSON.');
 const metadata={title_romaji:g('title_romaji'),title_english:g('title_english'),title_native:g('title_native'),title_french:g('title_french'),synonyms:g('synonyms').split('\n').map(x=>x.trim()).filter(Boolean).slice(0,30),synopsis:g('synopsis'),genres:g('genres').split(',').map(x=>x.trim()).filter(Boolean).slice(0,40),year:g('year')?Number(g('year')):null,format:g('format'),status:g('status'),airing_date:g('airing_date'),season:g('season'),episode_count:g('episode_count')?Number(g('episode_count')):null,duration_minutes:g('duration_minutes')?Number(g('duration_minutes')):null,studio:g('studio'),channel:g('channel'),score:g('score')?Number(g('score')):null,cover_url:safe(g('cover_url')),banner_url:safe(g('banner_url')),trailer_url:safe(g('trailer_url')),characters:chars.slice(0,40),external_links:links.filter(x=>x&&safe(x.url)).slice(0,40)};
 const name=metadata.title_french||metadata.title_english||metadata.title_romaji||metadata.title_native;if(!name)throw Error('Le titre est obligatoire.');
 return {name,metadata,anilist_id:g('anilist_id')?Number(g('anilist_id')):null,publication_state:g('publication_state'),publish_at:g('publish_at')?new Date(g('publish_at')).toISOString():null}
}
