function detectSource(raw){
 let value=String(raw||'').trim(),match=value.match(/<iframe[^>]+src\s*=\s*["']([^"']+)["']/i);if(match)value=match[1];
 try{const u=new URL(value);if(u.protocol!=='https:')return null;const h=u.hostname.toLowerCase();if(h==='youtu.be'||h==='youtube.com'||h.endsWith('.youtube.com'))return{url:value,type:'youtube'};if(h==='vimeo.com'||h.endsWith('.vimeo.com'))return{url:value,type:'vimeo'};if(/\.m3u8$/i.test(u.pathname))return{url:value,type:'hls'};if(/\.(mp4|webm|ogg)$/i.test(u.pathname))return{url:value,type:'mp4'};return{url:value,type:match?'embed':'external'}}catch{return null}
}
